#!/usr/bin/env python3
"""
Fix Observed Scene: puts the card's two files at their finished, tested version, whatever state
they are in now - so no missing earlier patch can block it. The scene's radar-acquisition scan
then waits until the scene image itself is on screen, and plays in full as you scroll to it; the
outline sits exactly on the slick; the fingerprint panel matches the image's height.

Whatever it replaces is first copied to .restore_backup/. Run from the repository root.
Safe to re-run.
"""
import os, shutil, sys, time
FILES = {'frontend/src/cards/ObservedSceneCard.jsx': 'import { Badge, Card } from \'../ui/primitives\';\nimport { HowMeasured } from \'../ui/viz\';\nimport { useCountUp } from \'../ui/useCountUp\';\nimport { useInView } from \'../ui/useInView\';\nimport \'./observedScene.css\';\nimport { CAPTIONS as C } from \'../ui/glossary\';\n\n/**\n * Values are shown at the precision the detection artifact rounds them to.\n *\n * The observed scene with the detector\'s outline drawn on it, and the\n * outline\'s measurements. The raw image alone proves nothing; the outline is\n * what the classical baseline detector retained.\n */\nexport default function ObservedSceneCard({ meta, slick, sceneUrl, nVessels }) {\n  // the acquisition plays when the scene image itself is mostly on screen - the card\'s top edge\n  // entering is too early, and would play it below the bottom of the window\n  const [sceneRef, sceneSeen] = useInView({ threshold: 0.55 });\n  if (!meta) return null;\n  const synthetic = meta.provenance?.status === \'synthetic\';\n  const b = meta.bbox;\n  const g = slick?.geometry;\n  const pts = (slick?.polygon ?? []).map(([lon, lat]) => {\n    const x = ((lon - b.min_lon) / (b.max_lon - b.min_lon)) * 100;\n    const y = ((b.max_lat - lat) / (b.max_lat - b.min_lat)) * 100;\n    return `${x.toFixed(2)},${y.toFixed(2)}`;\n  }).join(\' \');\n\n  return (\n    <Card title="Observed Scene"\n          badge={<Badge tone={synthetic ? \'warning\' : \'accent\'}>{synthetic ? \'synthetic\' : \'real\'}</Badge>}\n          caption="The dark, smooth patch the detector outlined. Radar darkness alone is not proof of oil.">\n      <div className="os">\n        <div ref={sceneRef} className={`scene-wrap os-scene${sceneSeen ? \' is-playing\' : \'\'}`}>\n          <img className="scene-img" src={sceneUrl} alt="Radar scene of the incident area" />\n          {pts && (\n            <svg className="scene-overlay" viewBox="0 0 100 100" preserveAspectRatio="none" role="img"\n                 aria-label={`Detected slick outline covering ${g?.area_km2} square kilometres`}>\n              <polygon points={pts} className="scene-poly" pathLength="100" />\n            </svg>\n          )}\n          {slick && !slick.detected && <div className="scene-nodetect">No slick detected</div>}\n          {/* the scene\'s facts as a viewfinder HUD, on the image itself */}\n          <span className="os-hud is-top">\n            <span className="os-chip">{meta.pixel_spacing_m} m pixels</span>\n            <span className="os-chip">{nVessels} vessels tracked</span>\n          </span>\n          <span className="os-hud is-bottom">\n            <span className="os-chip is-mono">{meta.acquired_utc.slice(11, 16)} UTC · {meta.acquired_utc.slice(0, 10)}</span>\n            {slick?.truth_agreement_iou != null && (\n              <span className="os-chip is-truth"><i style={{ \'--v\': slick.truth_agreement_iou }} />{slick.truth_agreement_iou.toFixed(2)} match with the generator\'s mask</span>\n            )}\n          </span>\n          {/* a radar acquisition: a veil lifts behind a sweeping scan line, then the outline draws in */}\n          <span className="os-scan" aria-hidden="true"><i className="os-scan-veil" /><i className="os-scan-line" /></span>\n        </div>\n\n        {g && (\n          <div className="os-print">\n            <span className="os-eyebrow">Slick fingerprint</span>\n            <ShapeGlyph major={g.major_axis_km} minor={g.minor_axis_km} bearing={g.orientation_deg_from_north} />\n            <span className="os-big"><Count value={g.area_km2} decimals={0} /><small> km²</small></span>\n            <span className="os-hero-label">sea surface covered</span>\n            <div className="os-grid">\n              <div><b>{g.perimeter_km.toFixed(1)}</b><span>km edge</span></div>\n              <div><b>{g.major_axis_km.toFixed(1)} × {g.minor_axis_km.toFixed(1)}</b><span>km across</span></div>\n              <div><b>{g.orientation_deg_from_north.toFixed(0)}°</b><span>from north</span></div>\n              <div><b>{g.elongation.toFixed(2)}</b><span>elongation</span></div>\n            </div>\n            <ElongationBar value={g.elongation} />\n          </div>\n        )}\n      </div>\n\n      <HowMeasured>\n        <dl>\n          <dt>Detector</dt><dd>{slick?.detector}. {C.darkness}</dd>\n          {g && <>\n            <dt>Area and edge</dt><dd>{C.area} {C.perimeter}</dd>\n            <dt>Shape</dt><dd>Long axis {g.major_axis_km.toFixed(2)} km, short axis {g.minor_axis_km.toFixed(2)} km. {C.elongation} {C.bearing}</dd>\n          </>}\n          {slick?.truth_agreement_iou != null && <><dt>Match with the generator\'s mask</dt><dd>{C.truthIou}</dd></>}\n          <dt>Measurement</dt><dd>{slick?.measurement_note}</dd>\n          <dt>Downstream</dt><dd>{slick?.downstream_note}</dd>\n        </dl>\n      </HowMeasured>\n    </Card>\n  );\n}\n\n/** The slick\'s shape, drawn to its measured axes and bearing, north up. */\nfunction ShapeGlyph({ major, minor, bearing }) {\n  const S = 62 / Math.max(major, 1e-6);                  // the long axis fills the glyph\n  const rx = (major / 2) * S, ry = (minor / 2) * S;\n  return (\n    <svg className="os-glyph" viewBox="-40 -40 80 80" role="img"\n         aria-label={`Slick shape: ${major.toFixed(1)} by ${minor.toFixed(1)} kilometres, long axis ${bearing.toFixed(0)} degrees from north`}>\n      <circle r="37" className="os-glyph-ring" />\n      <path d="M0 -37 L0 -31" className="os-glyph-tick" />\n      <text x="0" y="-26" className="os-glyph-n">N</text>\n      <g transform={`rotate(${bearing - 90})`}>\n        <ellipse rx={rx} ry={ry} className="os-glyph-shape" pathLength="100" />\n        <line x1={-rx} y1="0" x2={rx} y2="0" className="os-glyph-axis" />\n        <line x1="0" y1={-ry} x2="0" y2={ry} className="os-glyph-axis is-minor" />\n      </g>\n    </svg>\n  );\n}\n\n/** Where the elongation falls between round (1) and streak-like (5 and beyond). */\nfunction ElongationBar({ value }) {\n  const f = Math.max(0, Math.min(1, Math.log(value) / Math.log(5)));\n  return (\n    <div className="os-elong" aria-hidden="true">\n      <span>round</span><div className="os-elong-track"><i style={{ left: `${f * 100}%` }} /></div><span>streak</span>\n    </div>\n  );\n}\n\nfunction Count({ value, decimals }) {\n  const [ref, seen] = useInView();\n  return <span ref={ref}>{useCountUp(value, { decimals, duration: 1000, run: seen })}</span>;\n}\n', 'frontend/src/cards/observedScene.css': '/* Observed Scene: the image, and the slick\'s fingerprint beside it. */\n.os { display: grid; grid-template-columns: minmax(0, 1.25fr) minmax(0, 1fr); gap: var(--space-5); align-items: stretch; }\n.os-scene { position: relative; border-radius: 14px; overflow: hidden; box-shadow: inset 0 0 0 0.5px var(--separator-strong); }\n.os-scene .scene-img { display: block; width: 100%; height: 100%; object-fit: cover; }\n.os-stamp { position: absolute; left: 10px; bottom: 10px; padding: 3px 9px; border-radius: 999px; font-family: var(--font-mono);\n            font-size: var(--font-size-xxs); color: #fff; background: rgba(0, 0, 0, 0.55);\n            -webkit-backdrop-filter: blur(8px); backdrop-filter: blur(8px); }\n.os-print { display: flex; flex-direction: column; justify-content: center; gap: var(--space-4); padding: 16px; border-radius: 14px; background: var(--fill-pressed); }\n.os-eyebrow { font-size: var(--font-size-xxs); font-weight: var(--font-weight-semibold); text-transform: uppercase; letter-spacing: 0.07em; color: var(--label-2); }\n.os-print-row { display: flex; align-items: center; gap: var(--space-4); }\n.os-glyph { flex: none; width: 118px; height: 118px; overflow: visible; }\n.os-glyph-ring { fill: none; stroke: var(--separator-strong); stroke-width: 0.8; stroke-dasharray: 1.5 2.5; }\n.os-glyph-tick { stroke: var(--label-2); stroke-width: 1.4; stroke-linecap: round; }\n.os-glyph-n { font-size: 6px; font-weight: 700; text-anchor: middle; fill: var(--label-2); font-family: var(--font-body); }\n.os-glyph-shape { fill: rgba(10, 132, 255, 0.16); stroke: #64d2ff; stroke-width: 1.6; stroke-dasharray: 100; stroke-dashoffset: 100;\n                  animation: os-draw 1100ms 200ms cubic-bezier(0.22, 1, 0.36, 1) forwards; filter: drop-shadow(0 0 4px rgba(100, 210, 255, 0.5)); }\n.os-glyph-axis { stroke: var(--label-2); stroke-width: 0.7; stroke-dasharray: 2 2; opacity: 0; animation: os-fade 400ms 900ms forwards; }\n@keyframes os-draw { to { stroke-dashoffset: 0; } }\n@keyframes os-fade { to { opacity: 1; } }\n.os-hero { display: flex; flex-direction: column; min-width: 0; }\n.os-big { font-family: var(--font-display); font-size: 40px; font-weight: 600; letter-spacing: -0.03em; line-height: 1;\n          font-variant-numeric: tabular-nums; color: var(--label-1); }\n.os-big small { font-size: 16px; font-weight: 500; color: var(--label-2); letter-spacing: 0; }\n.os-hero-label { margin-top: 4px; font-size: var(--font-size-xs); color: var(--label-2); }\n.os-facts { display: flex; flex-wrap: wrap; gap: 4px 12px; margin-top: 10px; font-size: var(--font-size-xs); color: var(--label-2); }\n.os-facts b { color: var(--label-1); font-weight: var(--font-weight-semibold); font-variant-numeric: tabular-nums; }\n.os-elong { display: flex; align-items: center; gap: 8px; margin-top: 10px; font-size: var(--font-size-xxs); color: var(--label-3); }\n.os-elong-track { position: relative; flex: 1; height: 4px; border-radius: 2px; background: linear-gradient(90deg, rgba(100, 210, 255, 0.25), rgba(100, 210, 255, 0.7)); }\n.os-elong-track i { position: absolute; top: 50%; width: 10px; height: 10px; margin: -5px 0 0 -5px; border-radius: 50%; background: #fff;\n                    box-shadow: 0 0 0 2px #0a84ff, 0 1px 3px rgba(0, 0, 0, 0.3); }\n.os-chips { display: flex; flex-wrap: wrap; gap: 6px; }\n.os-chip { display: inline-flex; align-items: center; gap: 6px; padding: 4px 10px; border-radius: 999px; font-size: var(--font-size-xs);\n           color: var(--label-1); background: var(--card-bg, var(--content-bg)); box-shadow: inset 0 0 0 0.5px var(--separator); }\n.os-chip.is-truth i { width: 12px; height: 12px; border-radius: 50%;\n                      background: conic-gradient(var(--status-green) calc(var(--v) * 360deg), var(--fill-pressed) 0); }\n@media (max-width: 900px) { .os { grid-template-columns: 1fr; } }\n@media (prefers-reduced-motion: reduce) { .os-glyph-shape { animation: none; stroke-dashoffset: 0; } .os-glyph-axis { animation: none; opacity: 1; } }\n\n/* ---- redesign: a viewfinder HUD on the image, and a fingerprint that fills its panel */\n.os-scene { min-height: 300px; }\n.os-hud { position: absolute; left: 12px; right: 12px; display: flex; flex-wrap: wrap; gap: 6px; pointer-events: none; z-index: 2; }\n.os-hud.is-top { top: 12px; } .os-hud.is-bottom { bottom: 12px; }\n.os-hud .os-chip { color: #fff; background: rgba(8, 12, 18, 0.55); box-shadow: inset 0 0 0 0.5px rgba(255, 255, 255, 0.18);\n                   -webkit-backdrop-filter: blur(10px) saturate(140%); backdrop-filter: blur(10px) saturate(140%); }\n.os-hud .os-chip.is-mono { font-family: var(--font-mono); }\n.os-stamp { display: none; }\n/* a slow radar sweep across the scene, once, when it comes into view */\n.os-scanline { position: absolute; inset: 0; pointer-events: none; z-index: 1;\n               background: linear-gradient(180deg, transparent 0%, rgba(100, 210, 255, 0.16) 48%, rgba(100, 210, 255, 0.34) 50%, transparent 52%);\n               background-size: 100% 220%; background-position: 0 120%; opacity: 0;\n               animation: os-sweep 2200ms 300ms cubic-bezier(0.45, 0, 0.2, 1) backwards; }\n@keyframes os-sweep { 0% { opacity: 1; background-position: 0 120%; } 90% { opacity: 1; } 100% { opacity: 0; background-position: 0 -20%; } }\n.scene-poly { filter: drop-shadow(0 0 6px rgba(100, 210, 255, 0.8)); }\n\n.os-print { align-items: center; text-align: center; gap: 6px; padding: 18px 18px 16px; }\n.os-print .os-eyebrow { align-self: stretch; text-align: left; }\n.os-print .os-glyph { width: 150px; height: 150px; margin: 4px 0 2px; }\n.os-print .os-big { font-size: 44px; }\n.os-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; width: 100%; margin-top: 12px; }\n.os-grid > div { display: flex; flex-direction: column; gap: 1px; padding: 8px 10px; border-radius: 10px; text-align: left;\n                 background: var(--card-bg, var(--content-bg)); box-shadow: inset 0 0 0 0.5px var(--separator); }\n.os-grid b { font-size: var(--font-size-md); font-weight: var(--font-weight-semibold); color: var(--label-1); font-variant-numeric: tabular-nums; }\n.os-grid span { font-size: var(--font-size-xxs); color: var(--label-3); text-transform: uppercase; letter-spacing: 0.05em; }\n.os-print .os-elong { width: 100%; margin-top: 12px; }\n@media (prefers-reduced-motion: reduce) { .os-scanline { animation: none; } }\n\n/* the scene keeps its true proportions, so the outline lies exactly on the slick:\n   cropping the image to fill a taller box had shifted it out from under its outline */\n.os-scene { min-height: 0; align-self: start; }\n.os-scene .scene-img { height: auto; object-fit: fill; }\n\n/* the fingerprint panel takes exactly the image\'s height: it adds no height of its own to the\n   row (height 0) and stretches to it (min-height 100%); the shape glyph is the part that gives */\n.os { align-items: stretch; }\n.os-print { height: 0; min-height: 100%; box-sizing: border-box; justify-content: space-between; gap: 8px; overflow: hidden; }\n.os-print .os-glyph { flex: 1 1 0; width: auto; height: auto; min-height: 64px; max-height: 150px; aspect-ratio: 1; margin: 2px 0; }\n.os-print .os-grid { margin-top: 4px; }\n.os-print .os-elong { margin-top: 4px; }\n/* too narrow for the image to hold the fingerprint beside it: stack them, each full width */\n@media (max-width: 1320px) { .os { grid-template-columns: 1fr; } .os-print { height: auto; min-height: 0; } }\n\n/* ---- the scene\'s acquisition, when the card comes into view: a veil over the image lifts behind a\n   thin glowing scan line sweeping top to bottom, developing the image as it passes; once the sweep\n   has crossed the scene, the slick\'s outline draws itself in and its fill fades up */\n.os-scanline { display: none; }\n.os-scan { position: absolute; inset: 0; z-index: 1; pointer-events: none; overflow: hidden; }\n.os-scan-veil { position: absolute; inset: 0; background: rgba(6, 10, 18, 0.78);\n                -webkit-backdrop-filter: saturate(0.2) brightness(0.8); backdrop-filter: saturate(0.2) brightness(0.8);\n                animation: os-veil 1900ms cubic-bezier(0.45, 0, 0.25, 1) 250ms both; }\n@keyframes os-veil { from { clip-path: inset(0 0 0 0); } to { clip-path: inset(100% 0 0 0); } }\n.os-scan-line { position: absolute; left: 0; right: 0; top: 0; height: 110px; margin-top: -110px;\n                background: linear-gradient(180deg, transparent 0%, rgba(100, 210, 255, 0.06) 55%, rgba(100, 210, 255, 0.22) 92%, transparent 100%);\n                animation: os-line 1900ms cubic-bezier(0.45, 0, 0.25, 1) 250ms both; }\n.os-scan-line::after { content: ""; position: absolute; left: 0; right: 0; bottom: 0; height: 2px; background: #9fe7ff;\n                       box-shadow: 0 0 10px 2px rgba(100, 210, 255, 0.85), 0 0 28px 6px rgba(10, 132, 255, 0.45); }\n@keyframes os-line { 0% { top: 0; opacity: 1; } 88% { opacity: 1; } 100% { top: 100%; opacity: 0; } }\n.os-scene .scene-poly { stroke-dasharray: 100; stroke-dashoffset: 100; fill-opacity: 0;\n                        animation: os-poly-draw 900ms cubic-bezier(0.22, 1, 0.36, 1) 1700ms forwards, os-poly-fill 700ms ease 2200ms forwards; }\n@keyframes os-poly-draw { to { stroke-dashoffset: 0; } }\n@keyframes os-poly-fill { to { fill-opacity: 1; } }\n/* the HUD chips arrive once the scene is acquired */\n.os-hud { animation: os-hud-in 500ms ease 1900ms both; }\n@keyframes os-hud-in { from { opacity: 0; } }\n\n/* all of it waits, paused at its start, until the card scrolls into view */\n.panel:not(.is-inview) :is(.os-scan-veil, .os-scan-line, .scene-poly, .os-hud) { animation-play-state: paused; }\n\n@media (prefers-reduced-motion: reduce) {\n  .os-scan { display: none; }\n  .os-scene .scene-poly { animation: none; stroke-dashoffset: 0; fill-opacity: 1; }\n  .os-hud { animation: none; }\n}\n/* the acquisition waits until the scene image itself is on screen */\n.os-scene:not(.is-playing) :is(.os-scan-veil, .os-scan-line, .scene-poly, .os-hud) { animation-play-state: paused; }\n'}
NEEDS = ["frontend/src/ui/useInView.js", "frontend/src/ui/useCountUp.js", "frontend/src/ui/viz.jsx"]
if not os.path.isdir("frontend/src/cards"):
    sys.exit("ABORT: run this from the slick-trace repository root. Nothing was changed.")
missing = [n for n in NEEDS if not os.path.exists(n)]
if missing:
    sys.exit(f"ABORT: {', '.join(missing)} missing - an earlier design patch is not applied. Nothing was changed.")
had = "os-scene:not(.is-playing)" in open("frontend/src/cards/observedScene.css", encoding="utf-8").read() if os.path.exists("frontend/src/cards/observedScene.css") else False
print("scan-on-screen fix was already in your code:" , "yes" if had else "NO - that is why the scan did not play when you scrolled")
backup = os.path.join(".restore_backup", time.strftime("%Y%m%d-%H%M%S"))
written = 0
for p, text in FILES.items():
    if os.path.exists(p) and open(p, encoding="utf-8").read() == text:
        continue
    if os.path.exists(p):
        os.makedirs(os.path.dirname(os.path.join(backup, p)), exist_ok=True)
        shutil.copy2(p, os.path.join(backup, p))
    open(p, "w", encoding="utf-8").write(text)
    written += 1
print(f"Observed Scene: {written} files set to the finished version" + (f" (previous versions in {backup}/)" if written else " - already there"))
